ruleToc.chapterList:
@js:
var baseUrl = "https://www.lightnovel.fun/";
var apiUrl = "https://www.lightnovel.fun/api/pc-proxy/api/new-content-read/";
var headers = {
  "Referer": baseUrl,
  "User-Agent": "Mozilla/5.0 (Linux; Android 6.0; Nexus 5 Build/MRA58N) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/141.0.0.0 Mobile Safari/537.36",
  "Content-Type": "application/json; charset=UTF-8",
  "Cookie": cookie.getCookie(baseUrl)
};
function parseJson(text, label) {
  if (text === null || text === undefined || /^\s*$/.test(String(text))) {
    throw new Error("轻之国度" + label + "接口返回空响应，请确认已登录、Cookie 未过期，并稍后重试");
  }
  try {
    return JSON.parse(String(text));
  } catch (e) {
    throw new Error("轻之国度" + label + "接口返回的不是合法 JSON，请确认已登录并稍后重试");
  }
}
function postJson(path, body) {
  var response = java.post(apiUrl + path, JSON.stringify(body), headers);
  return parseJson(response ? response.body() : "", path);
}
function hasNext(data, page) {
  if (data && data.page_info && data.page_info.has_next !== undefined) {
    return data.page_info.has_next === 1 || data.page_info.has_next === true;
  }
  if (data && data.pagination && data.pagination.page_count !== undefined) {
    return page < Number(data.pagination.page_count);
  }
  return true;
}
var first = parseJson(src, "卷列表");
if (!first || first.code !== 0 || !first.data || !first.data.book_id) {
  throw new Error("??????获取目录链接时无法取得 book_id");
}
var resultList = [];
var volumePage = 1;
var volumeResponse = first;
var volumeGuard = 0;
while (volumeResponse && volumeResponse.data && volumeResponse.data.list && volumeResponse.data.list.length > 0 && volumeGuard < 100) {
  var volumes = volumeResponse.data.list;
  for (var i = 0; i < volumes.length; i++) {
    var volume = volumes[i];
    resultList.push(JSON.stringify({
      isVolume: true,
      title: volume.title || volume.origin_title || "未命名卷"
    }));
    var chapterPage = 1;
    var chapterGuard = 0;
    while (chapterGuard < 100) {
      var chapterResponse = postJson("get-volume-chapters", {
        book_id: volume.book_id,
        volume_id: volume.volume_id,
        page: chapterPage,
        pageSize: 50,
        page_size: 50
      });
      var chapters = chapterResponse && chapterResponse.data && chapterResponse.data.list;
      if (!chapters || chapters.length === 0) {
        break;
      }
      for (var j = 0; j < chapters.length; j++) {
        resultList.push(JSON.stringify(chapters[j]));
      }
      if (!hasNext(chapterResponse.data, chapterPage)) {
        break;
      }
      chapterPage++;
      chapterGuard++;
    }
  }
  if (!hasNext(volumeResponse.data, volumePage)) {
    break;
  }
  volumePage++;
  volumeGuard++;
  volumeResponse = postJson("get-book-volumes", {
    book_id: first.data.book_id,
    page: volumePage,
    pageSize: 50,
    page_size: 50
  });
}
resultList;

